00094 // ----------------------------------------------------------------------------------------
00095 template <typename TReal>
00096 AI_FORCE_INLINE
00097 aiMatrix4x4t<TReal>::aiMatrix4x4t (const aiMatrix3x3t<TReal>& m) {
00098     a1 = m.a1; a2 = m.a2; a3 = m.a3; a4 = static_cast<TReal>(0.0);
00099     b1 = m.b1; b2 = m.b2; b3 = m.b3; b4 = static_cast<TReal>(0.0);
00100     c1 = m.c1; c2 = m.c2; c3 = m.c3; c4 = static_cast<TReal>(0.0);
00101     d1 = static_cast<TReal>(0.0); d2 = static_cast<TReal>(0.0); d3 = static_cast<TReal>(0.0); d4 = static_cast<TReal>(1.0);
00102 }
00103 
00104 // ----------------------------------------------------------------------------------------
00105 template <typename TReal>
00106 AI_FORCE_INLINE
00107 aiMatrix4x4t<TReal>::aiMatrix4x4t (const aiVector3t<TReal>& scaling, const aiQuaterniont<TReal>& rotation, const aiVector3t<TReal>& position) {
00108     // build a 3x3 rotation matrix
00109     aiMatrix3x3t<TReal> m = rotation.GetMatrix();
00110 
00111     a1 = m.a1 * scaling.x;
00112     a2 = m.a2 * scaling.x;
00113     a3 = m.a3 * scaling.x;
00114     a4 = position.x;
00115 
00116     b1 = m.b1 * scaling.y;
00117     b2 = m.b2 * scaling.y;
00118     b3 = m.b3 * scaling.y;
00119     b4 = position.y;
00120 
00121     c1 = m.c1 * scaling.z;
00122     c2 = m.c2 * scaling.z;
00123     c3 = m.c3 * scaling.z;
00124     c4= position.z;
00125 
00126     d1 = static_cast<TReal>(0.0);
00127     d2 = static_cast<TReal>(0.0);
00128     d3 = static_cast<TReal>(0.0);
00129     d4 = static_cast<TReal>(1.0);
00130 }
