00132 // ----------------------------------------------------------------------------------------
00133 template <typename TReal>
00134 AI_FORCE_INLINE
00135 aiMatrix4x4t<TReal>& aiMatrix4x4t<TReal>::operator *= (const aiMatrix4x4t<TReal>& m) {
00136     *this = aiMatrix4x4t<TReal>(
00137         m.a1 * a1 + m.b1 * a2 + m.c1 * a3 + m.d1 * a4,
00138         m.a2 * a1 + m.b2 * a2 + m.c2 * a3 + m.d2 * a4,
00139         m.a3 * a1 + m.b3 * a2 + m.c3 * a3 + m.d3 * a4,
00140         m.a4 * a1 + m.b4 * a2 + m.c4 * a3 + m.d4 * a4,
00141         m.a1 * b1 + m.b1 * b2 + m.c1 * b3 + m.d1 * b4,
00142         m.a2 * b1 + m.b2 * b2 + m.c2 * b3 + m.d2 * b4,
00143         m.a3 * b1 + m.b3 * b2 + m.c3 * b3 + m.d3 * b4,
00144         m.a4 * b1 + m.b4 * b2 + m.c4 * b3 + m.d4 * b4,
00145         m.a1 * c1 + m.b1 * c2 + m.c1 * c3 + m.d1 * c4,
00146         m.a2 * c1 + m.b2 * c2 + m.c2 * c3 + m.d2 * c4,
00147         m.a3 * c1 + m.b3 * c2 + m.c3 * c3 + m.d3 * c4,
00148         m.a4 * c1 + m.b4 * c2 + m.c4 * c3 + m.d4 * c4,
00149         m.a1 * d1 + m.b1 * d2 + m.c1 * d3 + m.d1 * d4,
00150         m.a2 * d1 + m.b2 * d2 + m.c2 * d3 + m.d2 * d4,
00151         m.a3 * d1 + m.b3 * d2 + m.c3 * d3 + m.d3 * d4,
00152         m.a4 * d1 + m.b4 * d2 + m.c4 * d3 + m.d4 * d4);
00153     return *this;
00154 }
