00212 // ----------------------------------------------------------------------------------------
00213 template <typename TReal>
00214 AI_FORCE_INLINE aiMatrix4x4t<TReal>& aiMatrix4x4t<TReal>::Transpose() {
00215     // (TReal&) don't remove, GCC complains cause of packed fields
00216     std::swap( (TReal&)b1, (TReal&)a2);
00217     std::swap( (TReal&)c1, (TReal&)a3);
00218     std::swap( (TReal&)c2, (TReal&)b3);
00219     std::swap( (TReal&)d1, (TReal&)a4);
00220     std::swap( (TReal&)d2, (TReal&)b4);
00221     std::swap( (TReal&)d3, (TReal&)c4);
00222     return *this;
00223 }
00224 
00225 // ----------------------------------------------------------------------------------------
00226 template <typename TReal>
00227 AI_FORCE_INLINE
00228 TReal aiMatrix4x4t<TReal>::Determinant() const {
00229     return a1*b2*c3*d4 - a1*b2*c4*d3 + a1*b3*c4*d2 - a1*b3*c2*d4
00230         + a1*b4*c2*d3 - a1*b4*c3*d2 - a2*b3*c4*d1 + a2*b3*c1*d4
00231         - a2*b4*c1*d3 + a2*b4*c3*d1 - a2*b1*c3*d4 + a2*b1*c4*d3
00232         + a3*b4*c1*d2 - a3*b4*c2*d1 + a3*b1*c2*d4 - a3*b1*c4*d2
00233         + a3*b2*c4*d1 - a3*b2*c1*d4 - a4*b1*c2*d3 + a4*b1*c3*d2
00234         - a4*b2*c3*d1 + a4*b2*c1*d3 - a4*b3*c1*d2 + a4*b3*c2*d1;
00235 }
00236 
00237 // ----------------------------------------------------------------------------------------
00238 template <typename TReal>
00239 AI_FORCE_INLINE
00240 aiMatrix4x4t<TReal>& aiMatrix4x4t<TReal>::Inverse() {
00241     // Compute the reciprocal determinant
00242     const TReal det = Determinant();
00243     if(det == static_cast<TReal>(0.0))
00244     {
00245         // Matrix not invertible. Setting all elements to nan is not really
00246         // correct in a mathematical sense but it is easy to debug for the
00247         // programmer.
00248         const TReal nan = std::numeric_limits<TReal>::quiet_NaN();
00249         *this = aiMatrix4x4t<TReal>(
00250             nan,nan,nan,nan,
00251             nan,nan,nan,nan,
00252             nan,nan,nan,nan,
00253             nan,nan,nan,nan);
00254 
00255         return *this;
00256     }
00257 
00258     const TReal invdet = static_cast<TReal>(1.0) / det;
00259 
00260     aiMatrix4x4t<TReal> res;
00261     res.a1 = invdet  * (b2 * (c3 * d4 - c4 * d3) + b3 * (c4 * d2 - c2 * d4) + b4 * (c2 * d3 - c3 * d2));
00262     res.a2 = -invdet * (a2 * (c3 * d4 - c4 * d3) + a3 * (c4 * d2 - c2 * d4) + a4 * (c2 * d3 - c3 * d2));
00263     res.a3 = invdet  * (a2 * (b3 * d4 - b4 * d3) + a3 * (b4 * d2 - b2 * d4) + a4 * (b2 * d3 - b3 * d2));
00264     res.a4 = -invdet * (a2 * (b3 * c4 - b4 * c3) + a3 * (b4 * c2 - b2 * c4) + a4 * (b2 * c3 - b3 * c2));
00265     res.b1 = -invdet * (b1 * (c3 * d4 - c4 * d3) + b3 * (c4 * d1 - c1 * d4) + b4 * (c1 * d3 - c3 * d1));
00266     res.b2 = invdet  * (a1 * (c3 * d4 - c4 * d3) + a3 * (c4 * d1 - c1 * d4) + a4 * (c1 * d3 - c3 * d1));
00267     res.b3 = -invdet * (a1 * (b3 * d4 - b4 * d3) + a3 * (b4 * d1 - b1 * d4) + a4 * (b1 * d3 - b3 * d1));
00268     res.b4 = invdet  * (a1 * (b3 * c4 - b4 * c3) + a3 * (b4 * c1 - b1 * c4) + a4 * (b1 * c3 - b3 * c1));
00269     res.c1 = invdet  * (b1 * (c2 * d4 - c4 * d2) + b2 * (c4 * d1 - c1 * d4) + b4 * (c1 * d2 - c2 * d1));
00270     res.c2 = -invdet * (a1 * (c2 * d4 - c4 * d2) + a2 * (c4 * d1 - c1 * d4) + a4 * (c1 * d2 - c2 * d1));
00271     res.c3 = invdet  * (a1 * (b2 * d4 - b4 * d2) + a2 * (b4 * d1 - b1 * d4) + a4 * (b1 * d2 - b2 * d1));
00272     res.c4 = -invdet * (a1 * (b2 * c4 - b4 * c2) + a2 * (b4 * c1 - b1 * c4) + a4 * (b1 * c2 - b2 * c1));
00273     res.d1 = -invdet * (b1 * (c2 * d3 - c3 * d2) + b2 * (c3 * d1 - c1 * d3) + b3 * (c1 * d2 - c2 * d1));
00274     res.d2 = invdet  * (a1 * (c2 * d3 - c3 * d2) + a2 * (c3 * d1 - c1 * d3) + a3 * (c1 * d2 - c2 * d1));
00275     res.d3 = -invdet * (a1 * (b2 * d3 - b3 * d2) + a2 * (b3 * d1 - b1 * d3) + a3 * (b1 * d2 - b2 * d1));
00276     res.d4 = invdet  * (a1 * (b2 * c3 - b3 * c2) + a2 * (b3 * c1 - b1 * c3) + a3 * (b1 * c2 - b2 * c1));
00277     *this = res;
00278 
00279     return *this;
00280 }
00281 
00282 // ----------------------------------------------------------------------------------------
00283 template <typename TReal>
00284 AI_FORCE_INLINE
00285 TReal* aiMatrix4x4t<TReal>::operator[](unsigned int p_iIndex) {
00286     if (p_iIndex > 3) {
00287         return nullptr;
00288     }
00289     switch ( p_iIndex ) {
00290         case 0:
00291             return &a1;
00292         case 1:
00293             return &b1;
00294         case 2:
00295             return &c1;
00296         case 3:
00297             return &d1;
00298         default:
00299             break;
00300     }
00301     return &a1;
00302 }
00303 
00304 // ----------------------------------------------------------------------------------------
00305 template <typename TReal>
00306 AI_FORCE_INLINE
00307 const TReal* aiMatrix4x4t<TReal>::operator[](unsigned int p_iIndex) const {
00308     if (p_iIndex > 3) {
00309         return nullptr;
00310     }
00311 
00312     switch ( p_iIndex ) {
00313         case 0:
00314             return &a1;
00315         case 1:
00316             return &b1;
00317         case 2:
00318             return &c1;
00319         case 3:
00320             return &d1;
00321         default:
00322             break;
00323     }
00324     return &a1;
00325 }
