00329 AI_FORCE_INLINE
00330 bool aiMatrix4x4t<TReal>::operator== (const aiMatrix4x4t<TReal>& m) const {
00331     return (a1 == m.a1 && a2 == m.a2 && a3 == m.a3 && a4 == m.a4 &&
00332             b1 == m.b1 && b2 == m.b2 && b3 == m.b3 && b4 == m.b4 &&
00333             c1 == m.c1 && c2 == m.c2 && c3 == m.c3 && c4 == m.c4 &&
00334             d1 == m.d1 && d2 == m.d2 && d3 == m.d3 && d4 == m.d4);
00335 }
