00337 // ----------------------------------------------------------------------------------------
00338 template <typename TReal>
00339 AI_FORCE_INLINE
00340 bool aiMatrix4x4t<TReal>::operator!= (const aiMatrix4x4t<TReal>& m) const {
00341     return !(*this == m);
