00344 // ---------------------------------------------------------------------------
00345 template<typename TReal>
00346 AI_FORCE_INLINE
00347 bool aiMatrix4x4t<TReal>::Equal(const aiMatrix4x4t<TReal>& m, TReal epsilon) const {
00348     return
00349         std::abs(a1 - m.a1) <= epsilon &&
00350         std::abs(a2 - m.a2) <= epsilon &&
00351         std::abs(a3 - m.a3) <= epsilon &&
00352         std::abs(a4 - m.a4) <= epsilon &&
00353         std::abs(b1 - m.b1) <= epsilon &&
00354         std::abs(b2 - m.b2) <= epsilon &&
00355         std::abs(b3 - m.b3) <= epsilon &&
00356         std::abs(b4 - m.b4) <= epsilon &&
00357         std::abs(c1 - m.c1) <= epsilon &&
00358         std::abs(c2 - m.c2) <= epsilon &&
00359         std::abs(c3 - m.c3) <= epsilon &&
00360         std::abs(c4 - m.c4) <= epsilon &&
00361         std::abs(d1 - m.d1) <= epsilon &&
00362         std::abs(d2 - m.d2) <= epsilon &&
00363         std::abs(d3 - m.d3) <= epsilon &&
00364         std::abs(d4 - m.d4) <= epsilon;
00365 }
