00368 
00369 #define ASSIMP_MATRIX4_4_DECOMPOSE_PART     \
00370     const aiMatrix4x4t<TReal>& _this = *this;/* Create alias for conveniance. */ \
00371     \
00372     /* extract translation */ \
00373     pPosition.x = _this[0][3]; \
00374     pPosition.y = _this[1][3]; \
00375     pPosition.z = _this[2][3]; \
00376     \
00377     /* extract the columns of the matrix. */ \
00378     aiVector3t<TReal> vCols[3] = { \
00379         aiVector3t<TReal>(_this[0][0],_this[1][0],_this[2][0]), \
00380         aiVector3t<TReal>(_this[0][1],_this[1][1],_this[2][1]), \
00381         aiVector3t<TReal>(_this[0][2],_this[1][2],_this[2][2]) \
00382     }; \
00383     \
00384     /* extract the scaling factors */ \
00385     pScaling.x = vCols[0].Length(); \
00386     pScaling.y = vCols[1].Length(); \
00387     pScaling.z = vCols[2].Length(); \
00388     \
00389     /* and the sign of the scaling */ \
00390     if (Determinant() < 0) pScaling = -pScaling; \
00391     \
00392     /* and remove all scaling from the matrix */ \
00393     if(pScaling.x) vCols[0] /= pScaling.x; \
00394     if(pScaling.y) vCols[1] /= pScaling.y; \
00395     if(pScaling.z) vCols[2] /= pScaling.z; \
00396     \
00397     do {} while(false)
00398 
00399 template <typename TReal>
00400 AI_FORCE_INLINE
00401 void aiMatrix4x4t<TReal>::Decompose (aiVector3t<TReal>& pScaling, aiQuaterniont<TReal>& pRotation,
00402         aiVector3t<TReal>& pPosition) const {
00403     ASSIMP_MATRIX4_4_DECOMPOSE_PART;
00404 
00405     // build a 3x3 rotation matrix
00406     aiMatrix3x3t<TReal> m(vCols[0].x,vCols[1].x,vCols[2].x,
00407         vCols[0].y,vCols[1].y,vCols[2].y,
00408         vCols[0].z,vCols[1].z,vCols[2].z);
00409 
00410     // and generate the rotation quaternion from it
00411     pRotation = aiQuaterniont<TReal>(m);
00412 }
00413 
00414 template <typename TReal>
00415 AI_FORCE_INLINE
00416 void aiMatrix4x4t<TReal>::Decompose(aiVector3t<TReal>& pScaling, aiVector3t<TReal>& pRotation, aiVector3t<TReal>& pPosition) const {
00417     ASSIMP_MATRIX4_4_DECOMPOSE_PART;
00418 
00419     /*
00420     assuming a right-handed coordinate system
00421     and post-multiplication of column vectors,
00422     the rotation matrix for an euler XYZ rotation is M = Rz * Ry * Rx.
00423     combining gives:
00424 
00425         |  CE  BDE-AF  ADE+BF  0  |
00426     M = |  CF  BDF+AE  ADF-BE  0  |
00427         |  -D    CB      AC    0  |
00428         |   0     0       0    1  |
00429 
00430     where
00431     A = cos(angle_x), B = sin(angle_x);
00432     C = cos(angle_y), D = sin(angle_y);
00433     E = cos(angle_z), F = sin(angle_z);
00434     */
00435 
00436     // Use a small epsilon to solve floating-point inaccuracies
00437     const TReal epsilon = Assimp::Math::getEpsilon<TReal>();
00438 
00439     pRotation.y  = std::asin(-vCols[0].z);// D. Angle around oY.
00440 
00441     TReal C = std::cos(pRotation.y);
00442 
00443     if(std::fabs(C) > epsilon)
00444     {
00445         // Finding angle around oX.
00446         TReal tan_x = vCols[2].z / C;// A
00447         TReal tan_y = vCols[1].z / C;// B
00448 
00449         pRotation.x = std::atan2(tan_y, tan_x);
00450         // Finding angle around oZ.
00451         tan_x = vCols[0].x / C;// E
00452         tan_y = vCols[0].y / C;// F
00453         pRotation.z = std::atan2(tan_y, tan_x);
00454     }
00455     else
00456     {// oY is fixed.
00457         pRotation.x = 0;// Set angle around oX to 0. => A == 1, B == 0, C == 0, D == 1.
00458 
00459         // And finding angle around oZ.
00460         TReal tan_x =  vCols[1].y;// BDF+AE => E
00461         TReal tan_y = -vCols[1].x;// BDE-AF => F
00462 
00463         pRotation.z = std::atan2(tan_y, tan_x);
00464     }
00465 }
00466 
00467 #undef ASSIMP_MATRIX4_4_DECOMPOSE_PART
00468 
00469 template <typename TReal>
00470 AI_FORCE_INLINE
00471 void aiMatrix4x4t<TReal>::Decompose(aiVector3t<TReal>& pScaling, aiVector3t<TReal>& pRotationAxis, TReal& pRotationAngle,
00472                                             aiVector3t<TReal>& pPosition) const {
00473     aiQuaterniont<TReal> pRotation;
00474 
00475     Decompose(pScaling, pRotation, pPosition);
00476     pRotation.Normalize();
00477 
00478     TReal angle_cos = pRotation.w;
00479     TReal angle_sin = std::sqrt(1.0f - angle_cos * angle_cos);
00480 
00481     pRotationAngle = std::acos(angle_cos) * 2;
00482 
00483     // Use a small epsilon to solve floating-point inaccuracies
00484     const TReal epsilon = 10e-3f;
00485 
00486     if(std::fabs(angle_sin) < epsilon) angle_sin = 1;
00487 
00488     pRotationAxis.x = pRotation.x / angle_sin;
00489     pRotationAxis.y = pRotation.y / angle_sin;
00490     pRotationAxis.z = pRotation.z / angle_sin;
00491 }
00492 
00493 // ----------------------------------------------------------------------------------------
00494 template <typename TReal>
00495 AI_FORCE_INLINE
00496 void aiMatrix4x4t<TReal>::DecomposeNoScaling (aiQuaterniont<TReal>& rotation,
00497         aiVector3t<TReal>& position) const {
00498     const aiMatrix4x4t<TReal>& _this = *this;
00499 
00500     // extract translation
00501     position.x = _this[0][3];
00502     position.y = _this[1][3];
00503     position.z = _this[2][3];
00504 
00505     // extract rotation
00506     rotation = aiQuaterniont<TReal>((aiMatrix3x3t<TReal>)_this);
00507 }
