00510 template <typename TReal>
00511 AI_FORCE_INLINE
00512 aiMatrix4x4t<TReal>& aiMatrix4x4t<TReal>::FromEulerAnglesXYZ(const aiVector3t<TReal>& blubb) {
00513     return FromEulerAnglesXYZ(blubb.x,blubb.y,blubb.z);
00514 }
00515 
00516 // ----------------------------------------------------------------------------------------
00517 template <typename TReal>
00518 AI_FORCE_INLINE
00519 aiMatrix4x4t<TReal>& aiMatrix4x4t<TReal>::FromEulerAnglesXYZ(TReal x, TReal y, TReal z) {
00520     aiMatrix4x4t<TReal>& _this = *this;
00521 
00522     TReal cx = std::cos(x);
00523     TReal sx = std::sin(x);
00524     TReal cy = std::cos(y);
00525     TReal sy = std::sin(y);
00526     TReal cz = std::cos(z);
00527     TReal sz = std::sin(z);
00528 
00529     // mz*my*mx
00530     _this.a1 = cz * cy;
00531     _this.a2 = cz * sy * sx - sz * cx;
00532     _this.a3 = sz * sx + cz * sy * cx;
00533 
00534     _this.b1 = sz * cy;
00535     _this.b2 = cz * cx + sz * sy * sx;
00536     _this.b3 = sz * sy * cx - cz * sx;
00537 
00538     _this.c1 = -sy;
00539     _this.c2 = cy * sx;
00540     _this.c3 = cy * cx;
00541 
00542     return *this;
00543 }
00544 
00545 // ----------------------------------------------------------------------------------------
00546 template <typename TReal>
00547 AI_FORCE_INLINE
00548 bool aiMatrix4x4t<TReal>::IsIdentity() const {
00549     // Use a small epsilon to solve floating-point inaccuracies
00550     const static TReal epsilon = 10e-3f;
00551 
00552     return (a2 <= epsilon && a2 >= -epsilon &&
00553             a3 <= epsilon && a3 >= -epsilon &&
00554             a4 <= epsilon && a4 >= -epsilon &&
00555             b1 <= epsilon && b1 >= -epsilon &&
00556             b3 <= epsilon && b3 >= -epsilon &&
00557             b4 <= epsilon && b4 >= -epsilon &&
00558             c1 <= epsilon && c1 >= -epsilon &&
00559             c2 <= epsilon && c2 >= -epsilon &&
00560             c4 <= epsilon && c4 >= -epsilon &&
00561             d1 <= epsilon && d1 >= -epsilon &&
00562             d2 <= epsilon && d2 >= -epsilon &&
00563             d3 <= epsilon && d3 >= -epsilon &&
00564             a1 <= 1.f+epsilon && a1 >= 1.f-epsilon &&
00565             b2 <= 1.f+epsilon && b2 >= 1.f-epsilon &&
00566             c3 <= 1.f+epsilon && c3 >= 1.f-epsilon &&
00567             d4 <= 1.f+epsilon && d4 >= 1.f-epsilon);
00568 }
