00570 // ----------------------------------------------------------------------------------------
00571 template <typename TReal>
00572 AI_FORCE_INLINE
00573 aiMatrix4x4t<TReal>& aiMatrix4x4t<TReal>::RotationX(TReal a, aiMatrix4x4t<TReal>& out) {
00574     /*
00575          |  1  0       0       0 |
00576      M = |  0  cos(A) -sin(A)  0 |
00577          |  0  sin(A)  cos(A)  0 |
00578          |  0  0       0       1 |  */
00579     out = aiMatrix4x4t<TReal>();
00580     out.b2 = out.c3 = std::cos(a);
00581     out.b3 = -(out.c2 = std::sin(a));
00582     return out;
00583 }
00584 
00585 // ----------------------------------------------------------------------------------------
00586 template <typename TReal>
00587 AI_FORCE_INLINE
00588 aiMatrix4x4t<TReal>& aiMatrix4x4t<TReal>::RotationY(TReal a, aiMatrix4x4t<TReal>& out) {
00589     /*
00590          |  cos(A)  0   sin(A)  0 |
00591      M = |  0       1   0       0 |
00592          | -sin(A)  0   cos(A)  0 |
00593          |  0       0   0       1 |
00594         */
00595     out = aiMatrix4x4t<TReal>();
00596     out.a1 = out.c3 = std::cos(a);
00597     out.c1 = -(out.a3 = std::sin(a));
00598     return out;
00599 }
00600 
00601 // ----------------------------------------------------------------------------------------
00602 template <typename TReal>
00603 AI_FORCE_INLINE
00604 aiMatrix4x4t<TReal>& aiMatrix4x4t<TReal>::RotationZ(TReal a, aiMatrix4x4t<TReal>& out) {
00605     /*
00606          |  cos(A)  -sin(A)   0   0 |
00607      M = |  sin(A)   cos(A)   0   0 |
00608          |  0        0        1   0 |
00609          |  0        0        0   1 |   */
00610     out = aiMatrix4x4t<TReal>();
00611     out.a1 = out.b2 = std::cos(a);
00612     out.a2 = -(out.b1 = std::sin(a));
00613     return out;
00614 }
00615 
00616 // ----------------------------------------------------------------------------------------
00617 // Returns a rotation matrix for a rotation around an arbitrary axis.
00618 template <typename TReal>
00619 AI_FORCE_INLINE
00620 aiMatrix4x4t<TReal>& aiMatrix4x4t<TReal>::Rotation( TReal a, const aiVector3t<TReal>& axis, aiMatrix4x4t<TReal>& out) {
00621     TReal c = std::cos( a), s = std::sin( a), t = 1 - c;
00622     TReal x = axis.x, y = axis.y, z = axis.z;
00623 
00624     // Many thanks to MathWorld and Wikipedia
00625     out.a1 = t*x*x + c;   out.a2 = t*x*y - s*z; out.a3 = t*x*z + s*y;
00626     out.b1 = t*x*y + s*z; out.b2 = t*y*y + c;   out.b3 = t*y*z - s*x;
00627     out.c1 = t*x*z - s*y; out.c2 = t*y*z + s*x; out.c3 = t*z*z + c;
00628     out.a4 = out.b4 = out.c4 = static_cast<TReal>(0.0);
00629     out.d1 = out.d2 = out.d3 = static_cast<TReal>(0.0);
00630     out.d4 = static_cast<TReal>(1.0);
00631 
00632     return out;
00633 }
